parameters.jsonBody:
={{ JSON.stringify({
  model: $json.coderModel || "qwen2.5-coder:7b",
  stream: false,
  keep_alive: "5m",
  messages: [
    { role: "system", content: "You are the Coder for a coding task. You are given a task description, an implementation plan, and the CURRENT actual contents of the repository's source files. Write a unified diff (standard git diff format) that implements the change, using file paths exactly as shown (with a/ and b/ prefixes) and hunk context lines that match the ACTUAL current content exactly - never guess or invent code you have not seen. Output ONLY the diff text in the diff field - no prose, no markdown code fences inside it.

Example of the exact format required, including the required newline between the --- and +++ lines:
--- a/math.js
+++ b/math.js
@@ -1,3 +1,3 @@
 export function double(n) {
-  return n + n - 1;
+  return n * 2;
 }" },
    { role: "user", content: "Task: " + $('Prepare Row').item.json.task_description + "

Plan:
" + $('Parse Plan').item.json.plan + "

Current repository file contents:
" + ($('Fetch File Context').item.json.stdout ?? '(none found)') }
  ],
  format: {
    type: "object",
    properties: { diff: { type: "string" } },
    required: ["diff"]
  }
}) }}

parameters.jsCode:
let parsed;
try {
  parsed = JSON.parse($json.message?.content ?? '{}');
} catch (e) {
  parsed = {};
}
let diff = parsed.diff ?? '';
// Defensive repair #1, real observed model mistake: the --- and +++
// header lines run together on one line with no newline between them,
// which patch/git apply both reject as malformed. Prompt compliance
// alone (see Coder's system message, which includes a worked example)
// isn't trusted to prevent this.
diff = diff.replace(/(---\s+\S+)[ \t]+(\+\+\+\s+\S+)/g, '$1\n$2');
// Defensive repair #2, also observed with the example byte-verified
// correct in the prompt: unchanged context lines inside a hunk missing
// their required leading space marker (patch: "malformed patch" on an
// otherwise-correct hunk). Any non-empty line between an @@ hunk header
// and the next file/hunk marker that doesn't start with the three valid
// prefix characters (space/-/+) gets one prepended.
const lines = diff.split('\n');
let inHunk = false;
for (let i = 0; i < lines.length; i++) {
  const line = lines[i];
  if (/^@@/.test(line)) {
    inHunk = true;
    continue;
  }
  if (/^(---|\+\+\+|diff |index )/.test(line)) {
    inHunk = false;
    continue;
  }
  if (inHunk && line.length > 0 && !/^[ +-]/.test(line)) {
    lines[i] = ' ' + line;
  }
}
diff = lines.join('\n');
return [{ json: { diff } }];
